head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.clickBzProcsNo = "";
scwin.procJob = "";

// showObj(ObjID, flag) SetWindowPos(ObjID, nTop, nLeft, nWidth, nHeight)
// 세션정보를 얻기위한 함수사용

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        MaxTab_01.setSelectedTabIndex(1);
        await scwin.setCode();
        $c.cm.PanelToGroupBox(panel_Top);
        await scwin.listSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05900.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_LgcChk_onclick
 * @description btn_LgcChk 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_LgcChk_onclick = async function() {
    try {
        let dtsObj = scwin.getDataSet();
        if (scwin.selectIsuCheckCnt(dtsObj) === 0) {
            await $c.win.alert("[종목]을 선택하세요.");
            return;
        } else {
            $c.elw.fn_OpenLogicCheck();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05900.btn_LgcChk_onclick" });
    }
};

/**
 * @method
 * @name btn_RcvPrc_onclick
 * @description btn_RcvPrc 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_RcvPrc_onclick = async function() {
    try {
        if (js_svrGubun === 'dr') {
            await $c.win.alert("DR에서 운영될때는 서비스가 제공되지 않습니다.");
            return;
        }
        await scwin.packacpt();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05900.btn_RcvPrc_onclick" });
    }
};

/**
 * @method
 * @name btn_RetPrc_onclick
 * @description btn_RetPrc 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_RetPrc_onclick = async function() {
    try {
        await scwin.packret();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05900.btn_RetPrc_onclick" });
    }
};

