};

/**
 * @method
 * @name grd_List_1_OnDblClick
 * @description grd_List_1 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.grd_List_1_OnDblClick = function(row, colid) {
    try {
        if (colid === 'ISU_KOR_ABBRV') {
            scwin.openDetail(row, dts_List_1);
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05900.grd_List_1_OnDblClick" });
    }
};

/**
 * @method
 * @name grd_List_2_OnDblClick
 * @description grd_List_2 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
