 * @returns {void}
 * @hidden N
 */
scwin.grd_List_2_OnDblClick = function(row, colid) {
    try {
        if (colid === 'ISU_KOR_ABBRV') {
            scwin.openDetail(row, dts_List_2);
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05900.grd_List_2_OnDblClick" });
    }
};

/**
 * @method
 * @name trs_Save_OnFail
 * @description Save On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnFail = async function() {
    try {
        await $c.win.alert($c.stf.getMessageParam("MSG-A002", scwin.procJob));
        await $c.win.alert(trs_Save);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05900.trs_Save_OnFail" });
    }
};

/**
 * @method
 * @name trs_Save_OnSuccess
 * @description Save On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnSuccess = async function() {
    try {
        await $c.win.alert($c.stf.getMessageParam("MSG-0001", scwin.procJob));
        await scwin.listSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05900.trs_Save_OnSuccess" });
    }
};

/**
 * @method
 * @name btn_Close_onclick
 * @description btn_Close 클릭 이벤트
