        await scwin.listSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05900.MaxTab_01_OnSelChanged" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name setCode
 * @description set Code 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setCode = async function() {
    const sbmOptions = {
        id : "sbm_dts_ElwInst",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_ElwInst=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    // alert("call");

};

/**
 * @method
 * @name listSync
 * @description list Sync 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listSync = async function() {
    if (MaxTab_01.getSelectedTabIndex() === 1) {
        url += "&ISUR_CD=" + cmb_ISUR_CD.getValue();
        url += "&LIST_BZ_TP_CD=" + cmb_LIST_BZ_TP_CD.getValue();
        url += "&SCREN_ID=" + "ULDSTF05900.xml";
        url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
        const sbmOptions = {
            id : "sbm_dts_List_1",
            action : "/ElwListedReceive.do",
            ref : "",
            target : "dts_List_1=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    } else if (MaxTab_01.getSelectedTabIndex() === 2) {
        url += "&ISUR_CD=" + cmb_ISUR_CD.getValue();
        url += "&LIST_BZ_TP_CD=" + scwin.getListBzTpCd(cmb_LIST_BZ_TP_CD.getValue());
        url += "&SCREN_ID=" + "ULDSTF05900.xml";
        url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
        const sbmOptions = {
            id : "sbm_dts_List_2",
            action : "/ElwListedReceive.do",
            ref : "",
            target : "dts_List_2=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    }
};

/**
 * @method
 * @name packacpt
 * @description packacpt 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.packacpt = async function() {
    let dtsObj = scwin.getDataSet();
    let vSelectCnt = scwin.selectIsuCheckCnt(dtsObj);
    if (vSelectCnt === 0) {
        await $c.win.alert("[종목]을 선택하세요.");
        return;
    }
    if (!await scwin.checkForm("1")) {
        return;
    }
    scwin.procJob = ' 선택한 ' + vSelectCnt + '종목에대한 일괄접수처리 ';
    let res = window.confirm($c.stf.getMessageParam('MSG-A006', scwin.procJob));
    if (res) {
        // dts_Isu.UserStatus(1) = TB_JOB_UPDATE;
        for (let i = 1; i <= dtsObj.getRowCount(); i++) {
            if (dtsObj.getCellData(i, "CHECK") === "T") {
                dtsObj.setCellData(i, "LIST_PROCS_STAT_CD", ELW_RECV_PROC_CD_10);
            }
        }

        // alert('[dtsObj]'+dtsObj.text);
        trs_Save.KeyName = "toinb_dataid4";
        if (MaxTab_01.getSelectedTabIndex() === 1) {
            trs_Save.KeyValue = "JSP(I:pInput=dts_List_1)";
        } else if (MaxTab_01.getSelectedTabIndex() === 2) {
            trs_Save.KeyValue = "JSP(I:pInput=dts_List_2)";
        }
        const sbmOptions = {
            id : "sbm_trs_Save",
            action : "/ElwListedReceive.do",
            ref : "",
            target : "trs_Save=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
    }
};

/**
 * @method
 * @name packret
 * @description packret 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.packret = async function() {
    let dtsObj = scwin.getDataSet();
    let vSelectCnt = scwin.selectIsuCheckCnt(dtsObj);
    if (vSelectCnt === 0) {
        await $c.win.alert("[종목]을 선택하세요.");
        return;
    }
    if (!await scwin.checkForm("2")) {
        return;
    }
    scwin.procJob = ' 선택한 ' + vSelectCnt + '종목에대한 일괄반송처리 ';
    let res = window.confirm($c.stf.getMessageParam('MSG-A006', scwin.procJob));
    if (res) {
        // dts_Isu.UserStatus(1) = TB_JOB_UPDATE;
        for (let i = 1; i <= dtsObj.getRowCount(); i++) {
            if (dtsObj.getCellData(i, "CHECK") === "T") {
                dtsObj.setCellData(i, "LIST_PROCS_STAT_CD", ELW_RECV_PROC_CD_02);
                dtsObj.setCellData(i, "RET_RSN", cmb_RETN_BZ_TP_CD.getValue() + ":" + txb_RET_RSN.getValue());
            }
        }

        // alert('[dtsObj]'+dtsObj.text);
        trs_Save.KeyName = "toinb_dataid4";
        if (MaxTab_01.getSelectedTabIndex() === 1) {
            trs_Save.KeyValue = "JSP(I:pInput=dts_List_1)";
        } else if (MaxTab_01.getSelectedTabIndex() === 2) {
            trs_Save.KeyValue = "JSP(I:pInput=dts_List_2)";
        }
        const sbmOptions = {
            id : "sbm_trs_Save",
            action : "/ElwListedReceive.do",
            ref : "",
            target : "trs_Save=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
        txb_RET_RSN.setValue(""); // 초기화

    }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name getListBzTpCd
 * @description 추가상장신청시의 업무구분코드 가져오기
 * @param {String} str str
 * @returns {void}
 * @hidden N
 */
scwin.getListBzTpCd = function(str) {
    let val = '';
    if (str === LIST_BZ_TP_CD_002) {
        val = LIST_BZ_TP_CD_004;
    } else if (str === LIST_BZ_TP_CD_003) {
        val = LIST_BZ_TP_CD_005;
    }
    return val;
};

/**
 * @method
 * @name setBzProcsNo
 * @description set Bz Procs No 처리
 * @param {Object} obj 컴포넌트
 * @param {*} dtsObj dtsObj
 * @returns {void}
 * @hidden N
 */
scwin.setBzProcsNo = function(obj, dtsObj) {
    scwin.clickBzProcsNo = dtsObj.getCellData(Number(obj), "BZ_PROCS_NO");
    // alert("fn_setBzProcsNo():"+clickBzProcsNo);

};

/**
 * @method
 * @name openDetail
 * @description open Detail 처리
 * @param {Number} row 행 인덱스
 * @param {*} dtsObj dtsObj
 * @returns {void}
 * @hidden N
 */
scwin.openDetail = function(row, dtsObj) {
    scwin.setBzProcsNo(row, dtsObj);
    const vbzTpCd = dtsObj.getCellData(row, "LIST_BZ_TP_CD");
    $c.elw.fn_OpenDetailRecv(vbzTpCd);
};

/**
 * @method
 * @name getDataSet
 * @description get Data Set 처리
 * @returns {void}
 * @hidden N
 */
scwin.getDataSet = function() {
    let dtsObj;
    if (MaxTab_01.getSelectedTabIndex() === 1) {
        dtsObj = dts_List_1;
    } else if (MaxTab_01.getSelectedTabIndex() === 2) {
        dtsObj = dts_List_2;
    }
    return dtsObj;
};

/**
 * @method
 * @name selectIsuCheckCnt
 * @description select Isu Check Cnt 처리
 * @param {*} dtsObj dtsObj
 * @returns {void}
 * @hidden N
 */
scwin.selectIsuCheckCnt = function(dtsObj) {
    let k = 0;
    for (let i = 1; i <= dtsObj.getRowCount(); i++) {
        if (dtsObj.getCellData(i, "CHECK") === "T") {
            k++;
        }
    }
    return k;
};

/**
 * @method
 * @name checkForm
 * @description check Form 처리
 * @param {*} procTyp procTyp
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkForm = async function(procTyp) {
    if (procTyp === "2") {
        // jackal_12.08.01 반송구분추가 체크
        if (cmb_RETN_BZ_TP_CD.getValue() === "") {
            await $c.win.alert("[반송구분]를 선택하세요.");
            cmb_RETN_BZ_TP_CD.focus();
            return false;
        }
        if (txb_RET_RSN.getValue() === "") {
            await $c.win.alert("[반송사유]를 입력하세요.");
            txb_RET_RSN.focus();
            return false;
        }
    } else {
        // jackal_12.08.01 반송구분추가 체크
        if (cmb_RETN_BZ_TP_CD.getValue() !== "") {
            await $c.win.alert("반송시에만 [반송구분]를 선택하세요.");
            cmb_RETN_BZ_TP_CD.focus();
            return false;
        }
        if (txb_RET_RSN.getValue() !== "") {
            await $c.win.alert("반송시에만 [반송사유]를 입력하세요.");
            txb_RET_RSN.focus();
            return false;
        }
    }
    return true;
};

/**
 * @method
 * @name excelDown
 * @description 정보를 excel로 다운 받는다.
 * @returns {void}
 * @hidden N
 */
scwin.excelDown = function() {
    if (MaxTab_01.getSelectedTabIndex() === 1) {
        $c.data.downloadGridViewExcel(grd_List_1, {fileName: "신규상장접수목록", type: "8"});
    } else if (MaxTab_01.getSelectedTabIndex() === 2) {
        $c.data.downloadGridViewExcel(grd_List_2, {fileName: "추가상장접수목록", type: "8"});
    }
};

/**
 * @method
